    frontmatterRef.current = incoming.frontmatterBlock;
    backmatterRef.current = incoming.backmatterBlock;
    const currentBodyMarkdown = htmlToMarkdown(editor.getHTML());
    if (currentBodyMarkdown === incoming.body) {
      latestMarkdown.current = markdown;
      return;
    }
    isSyncing.current = true;
    editor.commands.setContent(markdownToHtml(incoming.body), {
      emitUpdate: false,
    });
    isSyncing.current = false;
    latestMarkdown.current = markdown;
  }, [editor, markdown]);

  useEffect(() => {
    const handleInsertRequest = (event: Event) => {
      const notePath = (event as CustomEvent<string>).detail;
      if (notePath) {
        pendingInsertDocumentKeyRef.current = notePath;
      }
    };
    window.addEventListener(NOTE_EDITOR_ENTER_INSERT_EVENT, handleInsertRequest);
    return () =>
      window.removeEventListener(
        NOTE_EDITOR_ENTER_INSERT_EVENT,
        handleInsertRequest
      );
  }, []);

  useEffect(() => {
    if (!editor || !documentKey || documentKey === lastDocumentKeyRef.current) {
      return;
    }
    lastDocumentKeyRef.current = documentKey;
    const shouldEnterInsertMode =
      pendingInsertDocumentKeyRef.current === documentKey;
    if (shouldEnterInsertMode) {
      pendingInsertDocumentKeyRef.current = null;
    }

    // Promoting a focused draft to a persisted note is not navigation: keep
    // the insertion point so background note creation never interrupts typing.
    if (
      !shouldEnterInsertMode &&
      editor.view.hasFocus() &&
      vimModeRef.current === "insert"
    ) {
      return;
    }

    resetForDocument(shouldEnterInsertMode ? "insert" : "normal");
    editor.view.dispatch(
      editor.view.state.tr
        .setSelection(TextSelection.atStart(editor.view.state.doc))
        .scrollIntoView()
    );
    if (scrollRef.current) {
      scrollRef.current.scrollTop = 0;
      scrollRef.current.scrollLeft = 0;
    }
    requestAnimationFrame(() => {
      if (shouldEnterInsertMode) {
        editor.commands.focus("start");
      } else {
        updateCursor(editor.view);
      }
        setSaveError(null);
        noteContentRef.current = content;
      }
    };

    void run();

    return () => {
      cancelled = true;
    };
  }, [activeNote, noteFileNameFormat, saveNow]);

  // Autosave with debounce
  useEffect(() => {
    if (!activeNote || !noteDirty) {
      return;
    }
    if (saveTimer.current) {
      window.clearTimeout(saveTimer.current);
    }
    saveTimer.current = window.setTimeout(() => {
      void saveNow(activeNote, noteContent);
    }, 400);
    return () => {
      if (saveTimer.current) {
        window.clearTimeout(saveTimer.current);
      }
    };
  }, [activeNote, noteContent, noteDirty, saveNow]);

  const handleEditorChange = useCallback(
    (markdown: string) => {
      if (!activeNote) {
        setDraftNoteContent((prev) => (prev === markdown ? prev : markdown));
        return;
      }
      setNoteContent((prev) => (prev === markdown ? prev : markdown));
      noteContentRef.current = markdown;
      setNoteDirty(true);
      noteDirtyRef.current = true;
      setSaveError(null);
    },
    [activeNote]
  );

  const clearNote = useCallback(() => {
    setNoteContent("");
    setNoteDirty(false);
    noteDirtyRef.current = false;
  }, []);

  const clearDraft = useCallback(() => {
    setDraftNoteContent("");
  }, []);

  const primeNoteContent = useCallback((markdown: string) => {
    setNoteContent(markdown);
    noteContentRef.current = markdown;
    setNoteDirty(false);
    noteDirtyRef.current = false;
    setSaveError(null);
  }, []);

  const flushSave = useCallback(async () => {
    if (saveTimer.current) {
      window.clearTimeout(saveTimer.current);
      saveTimer.current = null;
    }
    if (!activeNoteRef.current || !noteDirtyRef.current) {
      return;
    }
    await saveNow(activeNoteRef.current, noteContentRef.current);
  }, [saveNow]);

  const retrySave = useCallback(async () => {
    if (!activeNoteRef.current) {
      return;
    }
    await saveNow(activeNoteRef.current, noteContentRef.current);
  }, [saveNow]);

  useEffect(() => {
    return () => {
      if (saveTimer.current) {
        window.clearTimeout(saveTimer.current);
      }
    };
  }, []);

  const isSaved = !noteDirty && !isSaving && !saveError;

  return {
    noteContent,
    loadedNotePath,
    draftNoteContent,
    noteDirty,
    isSaving,
    saveError,
    isSaved,
    handleEditorChange,
    clearNote,
    clearDraft,
    primeNoteContent,
    flushSave,
    retrySave,
  };
}

