item.stdout:
/* The keys of a half-typed command (`3d`, `"a`, `ci`), shown as you type. */
.vim-pending-keys {
  margin-left: 6px;
  color: var(--ui-text);
  letter-spacing: 0;
}

.tiptap-content {
  min-height: 100%;
  padding: 10px 12px 16px 22px;
  color: var(--ui-text);
  font-size: var(--editor-font-size, 14px);
  line-height: 1.6;
  outline: none;
}

.app.sidebar-collapsed .tiptap-content {
  padding-left: clamp(56px, 20vw, 380px);
}

.tiptap-content p.is-editor-empty:first-child::before {
  content: attr(data-placeholder);
  color: #7a8593;
  font: 400 calc(var(--editor-font-size, 14px) + 1px) / 1.35 "Avenir Next", "SF Pro Text",
    "Segoe UI", "Noto Sans", Arial, sans-serif;
  letter-spacing: 0.01em;
  text-transform: none;
  float: left;
  height: 0;
  pointer-events: none;
}

.tiptap-editor[data-vim-mode="insert"]
  .tiptap-content
  p.is-editor-empty:first-child::before {
  content: none;
}

.tiptap-content p.is-editor-empty:first-child {
  margin: 0;
}

.tiptap-content::after {
  content: "";
  display: block;
  height: 18vh;
  min-height: 110px;
  pointer-events: none;
}

.tiptap-content h1,
.tiptap-content h2,
.tiptap-content h3 {
  margin: 0.8em 0 0.4em;
  font-weight: 650;
}

.tiptap-content p,
.tiptap-content ul,
.tiptap-content ol,
.tiptap-content blockquote {
  margin: 0.4em 0;
}

.tiptap-content blockquote {
  border-left: 3px solid var(--ui-border);
  padding-left: 10px;
  color: var(--ui-muted);
}

.tiptap-content code {
  background: rgba(127, 127, 127, 0.15);
  border-radius: 999px;
  background: rgba(41, 36, 33, 0.05);
  color: rgba(41, 36, 33, 0.62);
}

.app.theme-light .editor-lens-menu-trigger:hover {
  border: 0;
  background: rgba(41, 36, 33, 0.09);
  color: #292421;
}

.app.theme-light .tiptap-content {
  width: min(100%, calc(40rem + clamp(44px, 10vw, 128px)));
  margin: 0;
  padding: 14px clamp(22px, 5vw, 64px) 16px;
  color: var(--design-light-text);
  font-family: var(--design-font);
  font-size: clamp(var(--editor-font-size, 14px), 1.1vw, 16px);
  line-height: 1.52;
}

.app.theme-light .tiptap-content p.is-editor-empty:first-child::before {
  color: rgba(41, 36, 33, 0.45);
  font-family: var(--design-font);
}

.app.theme-light .tiptap-content blockquote {
  border-left-color: rgba(41, 36, 33, 0.2);
  color: rgba(41, 36, 33, 0.68);
}

.app.theme-light .tiptap-content code,
.app.theme-light .tiptap-content pre {
  background: rgba(41, 36, 33, 0.06);
}

.app.sidebar-collapsed .editor-top-row {
  padding-inline: clamp(56px, 20vw, 380px) clamp(22px, 5vw, 64px);
}

.app.sidebar-collapsed.theme-light .tiptap-content {
  width: 100%;
  max-width: none;
  padding-left: clamp(56px, 20vw, 380px);
  padding-right: clamp(56px, 20vw, 380px);
}

.app.theme-dark {
  background: var(--design-dark-selection);
  box-shadow: inset 2px 0 0 var(--design-dark-text);
}

.app.theme-dark .note-row.selected {
  background: var(--design-dark-selection);
  box-shadow: none;
}

.app.theme-dark .tiptap-content {
  padding: 14px clamp(22px, 5vw, 64px) 16px;
  font-family: var(--design-font);
  font-size: clamp(var(--editor-font-size, 14px), 1.1vw, 16px);
  line-height: 1.52;
}

@media (max-width: 760px) {
  .editor-top-row {
    padding: 8px 18px 0;
  }

  .app.theme-light .tiptap-content,
  .app.theme-dark .tiptap-content {
    padding-inline: 18px;
  }
}

/* Settings use dedicated classes because the unlayered `.pane-body` rule wins
   over Tailwind spacing utilities in this stylesheet. */
.settings-nav-pane {
  border-right: 0;
}

